import sqlite3

def validate_username(username):
    # Basic validation to check if username contains only alphanumeric characters
    return username.isalnum()

def test_sql_injection():
    # Attempt to inject SQL through username
    malicious_username = "admin' OR '1'='1"
    assert not validate_username(malicious_username), "SQL Injection vulnerability detected!"

test_sql_injection()
